CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile or superadmin" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.has_role(auth.uid(), 'super_admin'));
INSERT INTO public.profiles(id, display_name) SELECT id, COALESCE(raw_user_meta_data->>'full_name', '') FROM auth.users ON CONFLICT (id) DO NOTHING;
CREATE TABLE public.teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 100), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.teams TO authenticated;
GRANT ALL ON public.teams TO service_role;
ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.team_members (team_id uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(team_id, user_id));
GRANT SELECT ON public.team_members TO authenticated;
GRANT ALL ON public.team_members TO service_role;
ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read memberships" ON public.team_members FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'super_admin'));
CREATE POLICY "Read own teams" ON public.teams FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'super_admin') OR EXISTS (SELECT 1 FROM public.team_members m WHERE m.team_id = teams.id AND m.user_id = auth.uid()));
CREATE UNIQUE INDEX one_super_administrator ON public.user_roles(role) WHERE role = 'super_admin';
CREATE OR REPLACE FUNCTION public.is_member(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id = r.user_id WHERE r.user_id = _user_id AND p.active) $$;
CREATE OR REPLACE FUNCTION public.assign_role_for_user(_user_id uuid, _email text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (_user_id) ON CONFLICT (id) DO NOTHING; END $$;
COMMENT ON TABLE public.invitations IS 'DEPRECATED: accounts are created by the sole super administrator; no invitation claiming';
ALTER POLICY "Admins manage invitations delete" ON public.invitations USING (public.has_role(auth.uid(), 'super_admin'));
ALTER POLICY "Admins manage invitations insert" ON public.invitations WITH CHECK (public.has_role(auth.uid(), 'super_admin') AND invited_by = auth.uid());
ALTER POLICY "Admins manage invitations select" ON public.invitations USING (public.has_role(auth.uid(), 'super_admin'));
ALTER POLICY "Users read own roles" ON public.user_roles USING (user_id = auth.uid() OR public.has_role(auth.uid(), 'super_admin'));
ALTER POLICY "Owner select albums" ON public.albums USING (owner_id = auth.uid() AND public.is_member(auth.uid()));
ALTER POLICY "Owner update albums" ON public.albums USING (owner_id = auth.uid() AND public.is_member(auth.uid())) WITH CHECK (owner_id = auth.uid() AND public.is_member(auth.uid()));
ALTER POLICY "Owner delete albums" ON public.albums USING (owner_id = auth.uid() AND public.is_member(auth.uid()));
ALTER POLICY "Owner select results" ON public.photo_results USING (owner_id = auth.uid() AND public.is_member(auth.uid()));
ALTER POLICY "Owner insert results" ON public.photo_results WITH CHECK (owner_id = auth.uid() AND public.is_member(auth.uid()) AND EXISTS (SELECT 1 FROM public.albums a WHERE a.id = album_id AND a.owner_id = auth.uid()));
ALTER POLICY "Owner update results" ON public.photo_results USING (owner_id = auth.uid() AND public.is_member(auth.uid())) WITH CHECK (owner_id = auth.uid() AND public.is_member(auth.uid()) AND EXISTS (SELECT 1 FROM public.albums a WHERE a.id = album_id AND a.owner_id = auth.uid()));
ALTER POLICY "Owner delete results" ON public.photo_results USING (owner_id = auth.uid() AND public.is_member(auth.uid()));